#include <stdio.h>

int calc(int *arr, int size) {
    int sum = 0;
    for (int i = 0; i < size; i++) {
        if (arr[i] % 2 == 0) {
            sum += arr[i];
        } else {
            sum -= arr[i];
        }
    }
    return sum;
}

int main() {
    int arr[5] = {1, 2, 3, 4, 5};
